   153	function getFilterDisplayTitle(filters: Partial<SearchAdvancedFiltersForm>, fieldName: AdvancedFiltersKeys, translate: LocaleContextProps['translate']) {
   154	    if (fieldName === CONST.SEARCH.SYNTAX_FILTER_KEYS.DATE) {
   155	        // the value of date filter is a combination of dateBefore + dateAfter values
   156	        const {dateAfter, dateBefore} = filters;
   157	        let dateValue = '';
   158	        if (dateBefore) {
   159	            dateValue = translate('search.filters.date.before', {date: dateBefore});
   160	        }
   161	        if (dateBefore && dateAfter) {
   162	            dateValue += ', ';
   163	        }
   164	        if (dateAfter) {
   165	            dateValue += translate('search.filters.date.after', {date: dateAfter});
   166	        }
   167	
   168	        return dateValue;
   169	    }
   170	
   171	    if (fieldName === CONST.SEARCH.SYNTAX_FILTER_KEYS.AMOUNT) {
   172	        const {lessThan, greaterThan} = filters;
   173	        if (lessThan && greaterThan) {
   174	            return translate('search.filters.amount.between', {
   175	                lessThan: convertToDisplayStringWithoutCurrency(Number(lessThan)),
   176	                greaterThan: convertToDisplayStringWithoutCurrency(Number(greaterThan)),
   177	            });
   178	        }
   179	        if (lessThan) {
   180	            return translate('search.filters.amount.lessThan', {amount: convertToDisplayStringWithoutCurrency(Number(lessThan))});
   181	        }
   182	        if (greaterThan) {
   183	            return translate('search.filters.amount.greaterThan', {amount: convertToDisplayStringWithoutCurrency(Number(greaterThan))});
   184	        }
   185	        // Will never happen
   186	        return;
   187	    }
   188	
   189	    if (fieldName === CONST.SEARCH.SYNTAX_FILTER_KEYS.CURRENCY && filters[fieldName]) {
   190	        const filterArray = filters[fieldName] ?? [];
   191	        return filterArray.sort(localeCompare).join(', ');
   192	    }
   193	
   194	    if (fieldName === CONST.SEARCH.SYNTAX_FILTER_KEYS.CATEGORY && filters[fieldName]) {
   195	        const filterArray = filters[fieldName] ?? [];
   196	        return filterArray
   197	            .sort(sortOptionsWithEmptyValue)
   198	            .map((value) => (value === CONST.SEARCH.EMPTY_VALUE ? translate('search.noCategory') : value))
   199	            .join(', ');
   200	    }
   201	
   202	    if (fieldName === CONST.SEARCH.SYNTAX_FILTER_KEYS.TAG && filters[fieldName]) {
   203	        const filterArray = filters[fieldName] ?? [];
   204	        return filterArray
   205	            .sort(sortOptionsWithEmptyValue)
   206	            .map((value) => (value === CONST.SEARCH.EMPTY_VALUE ? translate('search.noTag') : value))
   207	            .join(', ');
   208	    }
   209	
   210	    if (fieldName === CONST.SEARCH.SYNTAX_FILTER_KEYS.DESCRIPTION) {
   211	        return filters[fieldName];
   212	    }
   213	
   214	    const filterValue = filters[fieldName];
   215	    return Array.isArray(filterValue) ? filterValue.join(', ') : filterValue;
   216	}
